/**
 * Build the optional Ship extension for `codsh --rust` (tickets 195, 196).
 * Bundles packages/bundle/src/ship-extension-hook.ts into
 * `<out>/hooks/ship-hook.mjs`, the browser graph server
 * (ship-extension-web-server.ts) into `<out>/hooks/ship-web.mjs`, the React
 * Flow page (ship-web-app.tsx, the same app legacy /ship serves) into
 * `<out>/web/ship-web.{js,css}`, and writes the `/ship` command the hook
 * prints to `<out>/commands/ship.md`. `<out>` defaults to
 * packages/cli/extensions/ship, whose manifest, hooks.json, and README are
 * checked in; the generated files are ignored by git.
 */
import { execFileSync } from 'node:child_process'
import { cpSync, existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { build } from 'esbuild'

const root = resolve(import.meta.dirname, '..')
export const SHIP_EXTENSION_SOURCE = join(root, 'packages', 'cli', 'extensions', 'ship')
const GENERATED = ['ship-hook.mjs', 'ship-web.mjs', 'commands', 'web']
const BANNER = '// Generated by scripts/build-ship-extension.mjs from packages/bundle/src/ship-extension*.ts. Do not edit.'

/** Build into `out` (copying the checked-in files first when out differs). */
export async function buildShipExtension(out = SHIP_EXTENSION_SOURCE) {
  if (resolve(out) !== SHIP_EXTENSION_SOURCE) {
    cpSync(SHIP_EXTENSION_SOURCE, out, {
      recursive: true,
      filter: source => !GENERATED.some(name => source.endsWith(name) || source.includes(`${join('ship', name)}`)),
    })
  }
  mkdirSync(join(out, 'hooks'), { recursive: true })
  mkdirSync(join(out, 'commands'), { recursive: true })
  mkdirSync(join(out, 'web'), { recursive: true })
  const hook = join(out, 'hooks', 'ship-hook.mjs')
  const node = {
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node22',
    legalComments: 'none',
    banner: { js: BANNER },
    logLevel: 'warning',
  }
  await build({ ...node, entryPoints: [join(root, 'packages', 'bundle', 'src', 'ship-extension-hook.ts')], outfile: hook })
  await build({ ...node, entryPoints: [join(root, 'packages', 'bundle', 'src', 'ship-extension-web-server.ts')], outfile: join(out, 'hooks', 'ship-web.mjs') })
  // The same page and settings as scripts/build-ship-web.mjs (legacy /ship).
  await build({
    entryPoints: [join(root, 'packages', 'bundle', 'src', 'ship-web-app.tsx')],
    outfile: join(out, 'web', 'ship-web.js'),
    bundle: true,
    minify: true,
    platform: 'browser',
    format: 'esm',
    target: ['es2022'],
    jsx: 'automatic',
    define: { 'process.env.NODE_ENV': '"production"' },
    legalComments: 'inline',
    logLevel: 'warning',
  })
  const command = execFileSync(process.execPath, [hook, '--print-command'], { encoding: 'utf8' })
  writeFileSync(join(out, 'commands', 'ship.md'), command)
  if (!existsSync(join(out, '.grok-plugin', 'plugin.json'))) throw new Error(`missing Ship extension manifest in ${out}`)
  for (const name of ['ship-web.js', 'ship-web.css']) {
    if (!existsSync(join(out, 'web', name))) throw new Error(`missing Ship browser asset ${name} in ${out}`)
  }
  return out
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const out = await buildShipExtension(process.argv[2] ? resolve(process.argv[2]) : undefined)
  console.log(`Built the Ship extension at ${out}`)
}
